//
// Backward (FlashAttentionV3Bwd950) kernel dispatch, split across per-
// (dtype, layout) router TUs and per-(dtype, layout, mask, deterministic,
// softcap) leaf TUs under autogen/ (generated by autogen/generate_kernels.py)
// so the 48 FlashAttentionV3Bwd950 instantiations compile in parallel: one per
// leaf TU. mha_bwd.cpp computes all host-side setup (tiling, workspace,
// layout) and hands the raw device pointers / scalars to
// launch_bwd<kInputLayout>(); it picks dtype at runtime and layout at the call
// site (compile time).
//
// This header stays free of the kernel templates (no fag_kernel.cpp): only
// kernel_operator.h is pulled in so the inline launch_bwd body can name
// bfloat16_t / half. The layout values mirror FAGTiling950::Layout
// (fag_common.h) but are carried as plain uint32_t so this header does not
// depend on the FAG headers; bwd_dispatch_variant_impl.hpp static-asserts
// that the two stay in sync.

#pragma once

#include <cstdint>
#include "acl/acl.h"
#include "kernel_operator.h" // bfloat16_t / half for the inline entry below

// Mirror of FAGTiling950::Layout (BSND = 0, TND = 1, BNSD = 2).
enum BwdInputLayout : uint32_t {
    BSND = 0,
    TND = 1,
    BNSD = 2,
};

struct BwdLaunchArgs {
    uint32_t blockDim;
    aclrtStream aclStream;
    bool is_bf16;
    bool is_softcap;
    bool has_attn_mask;
    bool deterministic;
    uint8_t* dOutDevice;
    uint8_t* qDevice;
    uint8_t* kDevice;
    uint8_t* vDevice;
    uint8_t* outDevice;
    uint8_t* attenMaskDevice;  // may be nullptr when has_attn_mask is false
    uint8_t* softMaxLseDevice;
    uint8_t* cuSeqQlenDevice;  // may be nullptr in BSND/BNSD mode
    uint8_t* cuSeqKvlenDevice; // may be nullptr in BSND/BNSD mode
    uint8_t* seqUsedQDevice;   // per-batch used Q lengths; nullptr when absent
    uint8_t* seqUsedKvDevice;  // per-batch used KV lengths; nullptr when absent
    uint8_t* dqDevice;
    uint8_t* dkDevice;
    uint8_t* dvDevice;
    uint8_t* workspaceDevice;
    uint8_t* tilingDevice;
};

// Per-(dtype, layout) router, defined in
// autogen/bwd_dispatch_<dtype>_<layout>.cpp via bwd_dispatch_impl.hpp. Each
// router TU resolves mask x deterministic x softcap at runtime and forwards to
// the matching leaf instantiation.
template <typename DType, uint32_t kInputLayout>
void bwd_dispatch_run(const BwdLaunchArgs& a);

// Runtime entry: kInputLayout is fixed at the call site, then the matching
// dtype's launcher is selected. bwd_dispatch_run is explicitly instantiated per
// (dtype, kInputLayout) in the autogen router TUs.
template <uint32_t kInputLayout>
inline void launch_bwd(const BwdLaunchArgs& a)
{
    if (a.is_bf16) {
        bwd_dispatch_run<bfloat16_t, kInputLayout>(a);
    } else {
        bwd_dispatch_run<half, kInputLayout>(a);
    }
}
